UPDATE ${tableName}
SET outbound_staff = #{outboundStaff,jdbcType=ARRAY,typeHandler=com.futurecraftsmen.pms.service.domain.ArrayTypeHandler}
WHERE primary_key in

    #{outboundOrderDetailCode}

update ${tableName}
set outbound_status = #{state}
where enterprise_code = #{enterpriseCode} and primary_key = #{primaryKey}

mapper.select:
select t.primary_key, p.product_part_sign, p.model, t.out_total, t.await_num, t.out_num, p.pcs, t.outbound_status, t.apply_details::BIGINT[], p.primary_key as productPartCode, s.total_inventory, s.lock_in_inventor, t.accrual_out_total, t.outbound_staff, t.accrual_lock_in_inventory, s.shipping_space::BIGINT[], t1.contract_number, s.stock_init_state, s.bar_code_number, t1.business_code, t1.outbound_type, s.primary_key stock from ${outboundOrderDetailTableName} t left join ${productPartTableName} p on t.product_or_part = p.primary_key left join ${stockTableName} s on t.product_or_part = s.product_part_code left join ${outboundOrderTableName} t1 on t.outbound_order = t1.primary_key where t.enterprise_code = #{enterpriseCode} and t.outbound_order = #{requestData.outboundOrderCode} and t.delete_flag = false
and ${dynamicTableNameProxy.getXiHangPartQuery("t.product_or_part","xihang",requestData.partUnityNo)}
AND (p.model like '%'|| #{requestData.searchName} ||'%' or p.product_part_sign like '%'|| #{requestData.searchName} ||'%')
and s.bar_code_number LIKE '%'|| #{requestData.barCodeNumber} ||'%'
and t.outbound_status in
#{code}
${dataScopeParams.dataScope}
order by t.create_time desc,t.id desc

select t.primary_key, p.product_part_sign, p.model, t.out_total, t.await_num, t.out_num, p.pcs, t.outbound_status, t.apply_details::BIGINT[], p.primary_key as productPartCode, s.total_inventory, s.lock_in_inventor, t.accrual_out_total, t.outbound_staff, t.accrual_lock_in_inventory, s.shipping_space::BIGINT[], t1.contract_number, s.stock_init_state, s.bar_code_number, t1.business_code, t1.outbound_type, s.primary_key stock from ${outboundOrderDetailTableName} t left join ${productPartTableName} p on t.product_or_part = p.primary_key left join ${stockTableName} s on t.product_or_part = s.product_part_code left join ${outboundOrderTableName} t1 on t.outbound_order = t1.primary_key where t.enterprise_code = #{enterpriseCode} and t.delete_flag = false
and t.outbound_order IN
#{code}
and t.outbound_order = #{requestData.outboundOrderCode}
and ( t1.outbound_type != #{typeCode} OR (t1.outbound_type = #{typeCode} AND t.accrual_out_total > 0) )
and ${dynamicTableNameProxy.getXiHangPartQuery("t.product_or_part","xihang",requestData.partUnityNo)}
AND (p.model like '%'|| #{requestData.searchName} ||'%' or p.product_part_sign like '%'|| #{requestData.searchName} ||'%')
and s.bar_code_number LIKE '%'|| #{requestData.barCodeNumber} ||'%'
and t.outbound_status in
#{code}
${dataScopeParams.dataScope}
order by t.create_time desc,t.id desc

select
    count(1)
from
    ${tableName}
where enterprise_code = #{enterpriseCode}
  and primary_key = #{primaryKey}
  and delete_flag = false

select t.primary_key, p.product_part_sign, p.model, t.out_total, t.await_num, t.out_num, p.pcs, t.outbound_status, t.apply_details::BIGINT[], p.primary_key as productPartCode, s.total_inventory, s.lock_in_inventor, t.accrual_out_total, t.outbound_staff, t.accrual_lock_in_inventory, s.shipping_space::BIGINT[], t1.contract_number, s.stock_init_state, s.bar_code_number, t1.business_code, t1.outbound_type, s.primary_key stock from ${outboundOrderDetailTableName} t left join ${productPartTableName} p on t.product_or_part = p.primary_key left join ${stockTableName} s on t.product_or_part = s.product_part_code left join ${outboundOrderTableName} t1 on t.outbound_order = t1.primary_key where t.enterprise_code = #{enterpriseCode} and t.delete_flag = false
and t.outbound_order IN
#{code}
and t.outbound_order = #{requestData.outboundOrderCode}
